struct nglListNode;

template <class T1, class T2>
struct pair {
    T1 first;
    T2 second;
};

typedef pair<nglListNode *, unsigned int> node_pair;

class nglTransCompare {
public:
    bool operator()(const node_pair& NodeA, const node_pair& NodeB) {
        if ((float&)NodeA.second > (float&)NodeB.second) return true;
        else if ((float&)NodeA.second < (float&)NodeB.second) return false;
        else return (unsigned int)NodeA.first < (unsigned int)NodeB.first;
    }
};

extern "C" void __push_heap(
    node_pair *, int, int, node_pair, nglTransCompare)
    __asm__("__push_heap__H4ZPt4pair2ZP11nglListNodeZUiZiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X11X11X21X31_v");
__asm__(".equ __push_heap__H4ZPt4pair2ZP11nglListNodeZUiZiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X11X11X21X31_v, 0x003AB4B0");

extern "C" void __adjust_heap(
    node_pair *, int, int, node_pair, nglTransCompare)
    __asm__("__adjust_heap__H4ZPt4pair2ZP11nglListNodeZUiZiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X11X11X21X31_v");

void __adjust_heap(node_pair* first, int holeIndex, int len,
                   node_pair value, nglTransCompare comp) {
    int topIndex = holeIndex;
    int secondChild = 2 * holeIndex + 2;
    while (secondChild < len) {
        if (comp(*(first + secondChild), *(first + (secondChild - 1))))
            secondChild--;
        *(first + holeIndex) = *(first + secondChild);
        holeIndex = secondChild;
        secondChild = 2 * (secondChild + 1);
    }
    if (secondChild == len) {
        *(first + holeIndex) = *(first + (secondChild - 1));
        holeIndex = secondChild - 1;
    }
    __push_heap(first, holeIndex, topIndex, value, comp);
}
